  name = 'World';
}
```
**3. Add the component to the Angular Module:**

Create a new Angular Module that will contain your shared component. For example, `shared.module.ts`.
```typescript
// shared.module.ts
import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { HelloComponent } from './hello.component';

@NgModule({
  imports: [CommonModule],
  declarations: [HelloComponent],
  exports: [HelloComponent]
})
export class SharedModule {}
```
**4. Export the Shared Module:**

Export the Shared Module from the `shared.module.ts` file.
```typescript
// shared.module.ts
