// Global variables
const numIterations = 5; // controls the depth of the fractal
const heartSize = 200; // size of the heart
const heartColor = [255, 0, 0, 255]; // red color

function setup() {
  createCanvas(400, 400, WEBGL);
  noStroke();
}

function draw() {
  background(255);

  // Set the camera position and angle
  orbitControls()

  // Draw the heart fractal
  drawFractal(heartSize, 0, 0, 1, numIterations);
}

// Function to draw the heart fractal
function drawFractal(size, x, y, z, iteration) {
  // Base case: if iteration reaches 0, draw a small heart
  if (iteration === 0) {
    drawHeart(size, x, y, z);
  } else {
    // Recursive case: draw a heart and then recurse on its daughters
    drawHeart(size, x, y, z);
    for (let i = 0; i < 2; i++) {
      let dx = x + (i === 0 ? 0.5 : -0.5) * size;
      let dy = y + (i === 0 ? 0.25 : -0.25) * size;
      drawFractal(size / 2, dx, dy, z, iteration - 1);
    }
  }
}

// Function to draw a small red heart
function drawHeart(size, x, y, z) {
  fill(heartColor[0], heartColor[1], heartColor[2], heartColor[3]);
  beginShape();
  vertex(x, y, z - size / 2);
  vertex(x + size / 2, y, z - size / 2);
  vertex(x + size / 2, y + size / 2, z - size / 2);
  vertex(x, y + size / 2, z - size / 2);
  endShape(CLOSE);
}

// Orbit controls to rotate the fractal
function orbitControls() {
  camera( cosmosCAA oracle, 200, PI/4, -PI/4 );
}
```
